import React, { useState, useEffect } from 'react';
import { usePaymentLogs } from '../hooks/usePaymentLogs';
import { formatCurrencyAndDate } from '../utils/helpers';

const TransactionHistory = ({ userId }) => {
  const { logs, loading } = usePaymentLogs(userId);
  const [displayLogs, setDisplayLogs] = useState([]);

  useEffect(() => {
    const formatted = logs.map(log => formatCurrencyAndDate(log));
    setDisplayLogs(formatted);
  }, [logs]); 

  if (loading) return <div>Loading...</div>;

  return (
    <ul>
      {displayLogs.map((log, index) => (
        <li key={index}>{log.formattedString}</li>
      ))}
    </ul>
  );
};

export default TransactionHistory;
```

